{
  "purpose": "Provides glom specs and utilities for lazily processing and transforming streaming iterable data.",
  "responsibilities": [
    "Defines the Iter spec for building lazy iterable transformation pipelines.",
    "Provides pipeline operators such as map, filter, chunked, windowed, split, flatten, unique, slice, takewhile, and dropwhile.",
    "Provides terminal and aggregation helpers such as all and first on stream pipelines.",
    "Defines the First spec for extracting the first matching item from an iterable."
  ],
  "key_symbols": [
    {
      "entity_id": "glom/streaming.py::glom.streaming.Iter",
      "behaviour": "Acts as glom's counterpart to Python's iter(), representing a streamable specification for iterable targets."
    },
    {
      "entity_id": "glom/streaming.py::glom.streaming.Iter.glomit",
      "behaviour": "Executes the streaming iterable specification against a target and scope."
    },
    {
      "entity_id": "glom/streaming.py::glom.streaming.Iter.map",
      "behaviour": "Returns a new Iter spec that applies a given subspec to each element in the stream."
    },
    {
      "entity_id": "glom/streaming.py::glom.streaming.Iter.filter",
      "behaviour": "Returns a new Iter spec that filters stream elements based on a key condition."
    },
    {
      "entity_id": "glom/streaming.py::glom.streaming.Iter.chunked",
      "behaviour": "Returns a new Iter spec that groups stream elements into chunks of a given size."
    },
    {
      "entity_id": "glom/streaming.py::glom.streaming.Iter.windowed",
      "behaviour": "Returns a new Iter spec that yields sliding windows of elements of a specified size."
    },
    {
      "entity_id": "glom/streaming.py::glom.streaming.Iter.split",
      "behaviour": "Returns a new Iter spec that lazily splits an iterable based on a separator."
    },
    {
      "entity_id": "glom/streaming.py::glom.streaming.Iter.flatten",
      "behaviour": "Returns a new Iter spec that flattens nested iterables into a single sequence."
    },
    {
      "entity_id": "glom/streaming.py::glom.streaming.Iter.unique",
      "behaviour": "Returns a new Iter spec that lazily deduplicates stream elements."
    },
    {
      "entity_id": "glom/streaming.py::glom.streaming.Iter.slice",
      "behaviour": "Returns a new Iter spec that trims iterables according to slicing parameters."
    },
    {
      "entity_id": "glom/streaming.py::glom.streaming.Iter.limit",
      "behaviour": "Convenience alias for slice that limits the stream to a specified count."
    },
    {
      "entity_id": "glom/streaming.py::glom.streaming.Iter.takewhile",
      "behaviour": "Returns a new Iter spec that yields items until a key condition becomes false."
    },
    {
      "entity_id": "glom/streaming.py::glom.streaming.Iter.dropwhile",
      "behaviour": "Returns a new Iter spec that drops stream items until a key condition is satisfied."
    },
    {
      "entity_id": "glom/streaming.py::glom.streaming.Iter.all",
      "behaviour": "Returns a new spec that consumes and returns all elements from the stream pipeline."
    },
    {
      "entity_id": "glom/streaming.py::glom.streaming.Iter.first",
      "behaviour": "Convenience method that yields the first truthy or matching item from the stream."
    },
    {
      "entity_id": "glom/streaming.py::glom.streaming.First",
      "behaviour": "Spec that retrieves the first element of an iterable matching a given key, with fallback to a default."
    },
    {
      "entity_id": "glom/streaming.py::glom.streaming.First.glomit",
      "behaviour": "Executes the First spec against a target iterable and scope."
    }
  ]
}
